import React, { useState } from 'react';
import './App.css';
import { fetchTimeline } from './api/jiraApi';
import MonthYearPicker from './components/MonthYearPicker';
import TimelineViewer from './components/TimelineViewer';
import TimelineChart from './components/TimelineChart';
import Heatmap from './components/Heatmap';

export default function App() {
  const [jiraKey, setJiraKey] = useState('');
  const [prUrl, setPrUrl] = useState('');
  const [timeline, setTimeline] = useState(null);
  const [loading, setLoading] = useState(false);
  const [darkMode, setDarkMode] = useState(false);
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');

  const handleGetTimeline = async () => {
    if (!jiraKey || !prUrl) {
      alert('Please enter Jira Key and PR URL');
      return;
    }

    setLoading(true);
    try {
      const response = await fetchTimeline({
        jiraKey,
        prUrl,
      });
      setTimeline(response.data);
    } catch (error) {
      alert('Error fetching timeline: ' + error.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className={darkMode ? 'dark-mode' : ''} style={styles.container}>
      <div style={styles.header}>
        <h1>📊 Jira Timeline Tracker</h1>
        <button
          onClick={() => setDarkMode(!darkMode)}
          style={styles.modeBtn}
        >
          {darkMode ? '☀️' : '🌙'}
        </button>
      </div>

      <div style={styles.card}>
        <h2>Get Timeline</h2>
        <div style={styles.form}>
          <input
            type="text"
            placeholder="Jira Issue Key (e.g., PROJ-123)"
            value={jiraKey}
            onChange={(e) => setJiraKey(e.target.value)}
            style={styles.input}
          />
          <input
            type="text"
            placeholder="GitHub PR URL"
            value={prUrl}
            onChange={(e) => setPrUrl(e.target.value)}
            style={styles.input}
          />
          <MonthYearPicker
            startDate={startDate}
            setStartDate={setStartDate}
            endDate={endDate}
            setEndDate={setEndDate}
          />
          <button
            onClick={handleGetTimeline}
            disabled={loading}
            style={styles.btn}
          >
            {loading ? 'Loading...' : 'Get Timeline'}
          </button>
        </div>
      </div>

      {timeline && (
        <div style={styles.results}>
          <TimelineViewer timeline={timeline} />
          <TimelineChart events={timeline.timeline} />
        </div>
      )}
    </div>
  );
}

const styles = {
  container: {
    minHeight: '100vh',
    background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
    padding: '20px',
    fontFamily: 'system-ui, -apple-system, sans-serif',
  },
  header: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: 30,
  },
  modeBtn: {
    background: 'rgba(255,255,255,0.2)',
    border: 'none',
    padding: '8px 12px',
    borderRadius: 8,
    cursor: 'pointer',
    fontSize: 18,
  },
  card: {
    background: 'rgba(255,255,255,0.1)',
    backdropFilter: 'blur(10px)',
    borderRadius: 12,
    padding: 24,
    marginBottom: 20,
    boxShadow: '0 8px 32px rgba(0,0,0,0.1)',
  },
  form: {
    display: 'flex',
    flexDirection: 'column',
    gap: 12,
  },
  input: {
    padding: '12px',
    borderRadius: 8,
    border: '1px solid rgba(255,255,255,0.3)',
    background: 'rgba(255,255,255,0.05)',
    color: 'white',
    fontSize: 14,
  },
  btn: {
    padding: '12px 24px',
    background: 'linear-gradient(135deg, #667eea, #764ba2)',
    color: 'white',
    border: 'none',
    borderRadius: 8,
    cursor: 'pointer',
    fontSize: 16,
    fontWeight: 600,
  },
  results: {
    marginTop: 20,
  },
};
